# Dennis R. Ottoson, « Toussaint Charbonneau, A Most Durable Man », South Dakota History, vol. 6, no 2 (1976), p. 152-185.
# PDF du Drive de l'auteur (HISTOIRE_LIVRES/JB_CHARBONNEAU), lu en entier le 19 novembre 2026. Corpus « Recherches », préfixe OT76.
# Seuls les épisodes absents de l'atlas sont retenus (Fort Mandan, Fort Manuel, Fort Clark et Fort Lisa sont déjà couverts).
from commun import Corpus
OT = "Ottoson, Dennis R. (1976), « Toussaint Charbonneau, A Most Durable Man », South Dakota History, vol. 6, no 2, p. 152-185"
C = Corpus('Recherches', 'OT76', OT, page_fmt='p. {}')
F = C.F
P = ['Toussaint Charbonneau']
F('01', "Fort Espérance (rivière Qu'Appelle) : Charbonneau, engagé du Nord-Ouest, va « courtiser la fille de Foutreau » (1793-1795)", 'personne', '1793-11/1795-05', -101.7, 50.48, 'a', P + ['John Macdonell', 'Cuthbert Grant', 'Peter Grant'],
  "Le journal du commis John Macdonell, du fort Espérance, mentionne Charbonneau à partir de novembre 1793 : il part avec quatre hommes pour le fort des Pins, fait la navette avec le poste de la rivière la Coquille, fait les courses entre le fort et les camps indiens. Au printemps 1795, revenu de la Montagne à la Bosse avec des marchandises, il y repart le 3 mars avec deux compagnons « pour courtiser la fille de Foutreau, une grande beauté ». Le 18 mai, il part avec Macdonell et la brigade d'été vers le Grand Portage.",
  '153', "Point au fort Espérance, sur la Qu'Appelle.")
F('02', "Portage la Prairie : l'incident du 30 mai 1795 rapporté par Macdonell", 'evenement', '1795-05-30', -98.4, 50.15, 'h', P + ['John Macdonell'],
  "Envoyé par-delà le portage de la Prairie vers le lac Manitoba, Charbonneau est surpris, selon le journal de Macdonell qui le tient d'ouï-dire, par une vieille Saulteuse qui l'accuse de violer sa fille ; elle le blesse avec une alêne à canot, si bien qu'il revient avec peine par le portage. Ottoson souligne que Charbonneau n'a jamais donné sa version et que Macdonell, surnommé « le Prêtre » par ses voyageurs, était d'une grande rigidité. Le journal s'achève peu après ; Charbonneau quitte la Compagnie du Nord-Ouest en 1796 pour le Missouri.",
  '154', "Témoignage indirect et unique. Point approximatif au bout du portage, côté lac Manitoba.")
F('03', "Ruisseau Charbonneau : la rivière qui porte son nom, borne du pays connu des Blancs (14 avril 1805)", 'lieu', '1805-04-14', -102.95, 47.75, 'a', P + ['Meriwether Lewis', 'William Clark'],
  "La veille, Charbonneau, « peut-être le plus timide marinier du monde » et qui ne sait pas nager, a failli renverser la pirogue blanche dans un coup de vent. Le 14 avril 1805, les capitaines donnent pourtant son nom à un ruisseau : c'est le point le plus haut du Missouri dont on sait avec certitude qu'un Blanc l'a atteint, Charbonneau y étant venu avec des chasseurs minitaris.",
  '161', "Point approximatif sur le Missouri en amont des villages de la Knife.")
F('04', "Embouchure de la Milk : le boudin blanc de Charbonneau (9 mai 1805)", 'evenement', '1805-05-09', -106.3, 48.05, 'a', P + ['Meriwether Lewis'],
  "Près de la rivière Milk, Charbonneau se rend populaire en préparant le boudin blanc, saucisse d'intestin de bison farcie de viande, de sel, de poivre et de farine, bouillie puis frite, que Lewis tient pour « l'un des plus grands délices de la forêt ». Il en refait aux Grandes Chutes ; quand l'expédition quitte les chutes, au-delà desquelles il n'y a plus de bisons, le boudin est « irrémédiablement perdu et Charbonneau sans emploi ».",
  '162-163', "")
F('05', "Près de la Musselshell : la pirogue blanche manque de chavirer et Sacagawea sauve les instruments (14 mai 1805)", 'evenement', '1805-05-14', -107.9, 47.6, 'a', P + ['Pierre Cruzatte', 'Sacagawea'],
  "Les deux capitaines sont à terre quand une rafale frappe la pirogue blanche que barre Charbonneau ; il la lofe, elle se couche, et il lâche la barre en implorant Dieu. Pierre Cruzatte, à la proue, menace de l'abattre s'il ne la reprend pas. Sacagawea, assise à l'arrière, recueille la plupart des objets qui flottent, livres, instruments et remèdes. Les capitaines remettent les hommes d'aplomb avec une ration d'eau-de-vie.",
  '162', "")
F('06', "Grandes Chutes du Missouri : la crue subite du ravin (29 juin 1805)", 'evenement', '1805-06-29', -111.2, 47.55, 'a', P + ['William Clark', 'Sacagawea', 'Jean-Baptiste Charbonneau', 'York'],
  "Surpris par un orage près des chutes, Clark abrite son petit groupe dans un ravin ; une crue subite le remplit. Sacagawea remonte la pente avec son fils nu dans les bras, tirée par Charbonneau et poussée par Clark. Ils perdent armes, parapluie, grande boussole et le berceau de cuir de Jean-Baptiste, et se remettent avec le grog de la gourde de York.",
  '163', "")
F('08', "Village kansa : Charbonneau, émissaire d'O'Fallon auprès des Kansas, et l'expédition de Long (août 1819)", 'evenement', '1819-08-10/1819-08-29', -96.6, 39.2, 'a', P + ['Benjamin O\'Fallon', 'Thomas Say'],
  "Interprète du gouvernement pour les Mandanes et les Minitaris, Charbonneau voyage avec l'agent Benjamin O'Fallon sur le vapeur Western Engineer. Au fort Osage, O'Fallon l'envoie par terre aux villages kansas, qui harcèlent les soldats, pour les convoquer à un conseil à l'île aux Vaches le 18 août. Il reste au village avec le naturaliste Thomas Say ; quand des Pawnees volent tous les chevaux du groupe de Say, il retourne à pied au village chercher du secours, puis rejoint le vapeur. Il fournit ensuite à Say ses renseignements sur les mœurs et la langue des Minitaris.",
  '174-175', "Point approximatif aux villages kansas de la rivière Kansas.")
F('09', "Fort Kiowa : Charbonneau et le duc Paul de Wurtemberg (25 août 1823)", 'evenement', '1823-08-25', -99.35, 43.95, 'a', P + ['Paul Wilhelm de Wurtemberg', 'Jean-Baptiste Charbonneau', 'Henry Leavenworth'],
  "Après l'attaque des Arikaras contre Ashley, Charbonneau a porté, le 14 août 1823, le calumet de paix de Leavenworth aux Arikaras, qui avaient abandonné leur village. Le 25 août, il attend au fort Recovery le duc Paul Wilhelm de Wurtemberg avec une invitation du bourgeois du fort Kiowa de la Compagnie française. Le duc, qui a rencontré le jeune Jean-Baptiste Charbonneau, dix-huit ans, sur la Kansas et projette de l'emmener en Europe, s'entretient sans doute longuement avec le père, qui donne son accord.",
  '176', "Point au fort Kiowa, près de l'actuel Chamberlain.")
F('10', "Rivière Cannonball : Charbonneau contourne à pied le village arikara ; Citoleux et ses hommes sont tués (octobre 1823)", 'evenement', '1823-10-11/1823-10-31', -100.6, 46.4, 'h', P + ['Antoine Citoleux', 'Joseph Brazeau'],
  "Malgré les assurances du vieux traiteur Joseph Brazeau, Charbonneau se méfie des Arikaras. Le 11 octobre 1823, il part du fort Kiowa en canot avec Antoine Citoleux et quatre hommes vers les Mandanes ; à une journée en aval du village arikara provisoire de la Cannonball, il quitte prudemment le canot et contourne le village à pied. Citoleux et les quatre autres ne reparaissent jamais : ils ont été tués au village. Arrivé seul chez les Mandanes, sans marchandises, Charbonneau passe au service de la Columbia Fur Company.",
  '177', "Point hypothétique sur le Missouri près de l'embouchure de la Cannonball.")
F('11', "Villages mandanes : interprète du traité Atkinson-O'Fallon (30 juillet 1825)", 'evenement', '1825-07-28/1825-08-06', -101.27, 47.25, 'c', P + ['Henry Atkinson', 'Benjamin O\'Fallon', 'Peter Wilson'],
  "Rentré le 28 juillet 1825 d'un village crow, Charbonneau trouve au poste mandane le général Atkinson et l'agent O'Fallon avec près de cinq cents soldats. Le 30 juillet, il est l'interprète des Mandanes et des Minitaris qui signent avec les États-Unis des traités de commerce et d'amitié. Le journal de l'expédition note qu'il a de nouveau une épouse, apparemment minitarie : le 6 août, « Shabano, sa femme et son frère » viennent passer la nuit au camp. Il aide ensuite le sous-agent Peter Wilson auprès des tribus d'amont.",
  '177-178', "Point au secteur des villages mandanes (fort Clark).")
F('12', "Village minitari : trois jours sur une meule de maïs pendant la crue du Missouri (6 avril 1826)", 'evenement', '1826-04-06/1826-04-09', -101.39, 47.33, 'a', P,
  "Le 6 avril 1826, le Missouri déborde au village minitari où vit Charbonneau. Il s'échappe avec une partie de ses biens, mais passe trois jours sur une meule de maïs, « sans feu, dans un vent froid du nord et la neige qui tourbillonnait », comme il le racontera au prince Maximilien.",
  '178', "Point au village d'Awatichai (Metaharta), sur la Knife.")
F('13', "Fort Clark : deux balles dans le chapeau du vieux Charbonneau (10 janvier 1836)", 'evenement', '1836-01-10', -101.275, 47.251, 'c', P + ['D. D. Mitchell'],
  "Le 10 janvier 1836, huit ou dix jeunes Yanktonais, seuls survivants d'une attaque des Minitaris et des Mandanes contre un camp de quarante-cinq loges sur la Knife, arrivent au fort Clark. Après leur récit, l'un d'eux tire sur un garçon gros ventre dans la chambre de l'interprète ; selon D. D. Mitchell, « le vieux Charbonneau l'a échappé belle, deux balles ayant traversé son chapeau ». Les Sioux repartent sans être inquiétés.",
  '181-182', "")
F('14', "Saint-Louis : congédié, le vieil interprète vient réclamer son salaire à Pilcher (21 août 1839)", 'personne', '1839-08-21', -90.19, 38.627, 'c', P + ['Joshua Pilcher'],
  "En juillet 1839, Charbonneau apprend que l'agent Fulkerson a été remplacé et que son emploi d'interprète est supprimé. Il descend aussitôt à Saint-Louis. Le surintendant Joshua Pilcher écrit qu'il est arrivé le 21 août des villages mandanes, à 1 600 milles, « chancelant sous les infirmités de quatre-vingts hivers, sans un dollar », et qu'il lui a payé ses deux premiers trimestres : « un fidèle serviteur du gouvernement, quoique dans une humble fonction », interprète aux Mandanes depuis quinze ans. On ignore la suite ; il est mort en août 1843.",
  '184', "")
fiches = C.fiches
